export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, minValue] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      if (!metric) {
        const validIds = evaluations.map((m) => m.id).join(', ');
        throw new Error(`Unknown metric: "${metricId}". Valid metric ids are: ${validIds}`);
      }

      const score = metric.score;
      const passed = score !== null && score >= minValue;
      thresholdResults.push({
        metric: metricId,
        min: minValue,
        score,
        passed
      });

      if (!passed) {
        allPassed = false;
      }
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

