      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('evaluates thresholds and passes when all meet minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 1.0,
        toxicity: 0.5
      }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      min: 1.0,
      passed: true
    });
  });

  it('evaluates thresholds and fails when any are not met', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['Goodbye']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9
      }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.9,
      passed: false
    });
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.5
      }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      score: null,
      passed: false
    });
  });

  it('throws on unknown metric in threshold', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: {
          unknown_metric: 0.5
        }
      });
