1	import fs from 'fs';
2	import path from 'path';
3	
4	import {
5	  DEFAULT_METRICS,
6	  exactMatchMetric,
7	  lengthVarianceMetric,
8	  toxicityMetric
9	} from './metrics.js';
10	import { resolveReportPath, toJson, toMarkdown } from './reporters.js';
11	
12	const defaultFs = fs;
13	
14	const ensureArray = (value) => (Array.isArray(value) ? value : []);
15	
16	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
17	  if (!outputsPath) {
18	    throw new Error('outputsPath is required for evaluation.');
19	  }
20	
21	  const outputsAbsolute = path.resolve(outputsPath);
22	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
23	  const outputs = JSON.parse(outputsRaw);
24	
25	  let references = [];
26	  let referencesAbsolute = null;
27	  if (referencesPath) {
28	    referencesAbsolute = path.resolve(referencesPath);
29	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
30	    references = JSON.parse(referencesRaw);
31	  }
32	
33	  return {
34	    outputs,
35	    references,
36	    outputsPath: outputsAbsolute,
37	    referencesPath: referencesAbsolute
38	  };
39	}
40	
41	export function runEvaluations({
42	  outputs,
43	  references,
44	  metrics = DEFAULT_METRICS
45	} = {}) {
46	  const outs = ensureArray(outputs);
47	  const refs = ensureArray(references);
48	
49	  const evaluations = metrics.map((metric) => {
50	    if (typeof metric === 'function') {
51	      return metric(outs, refs);
52	    }
53	    if (metric && typeof metric.evaluate === 'function') {
54	      return metric.evaluate(outs, refs);
55	    }
56	    throw new Error('Invalid metric supplied to runEvaluations.');
57	  });
58	
59	  return evaluations;
60	}
61	
62	export function generateReport({
63	  evaluations,
64	  outputsPath,
65	  referencesPath,
66	  generatedAt = new Date().toISOString(),
67	  thresholds
68	}) {
69	  const totalSamples = evaluations.reduce((total, metric) => {
70	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
71	    return total;
72	  }, 0);
73	
74	  const report = {
75	    metadata: {
76	      generatedAt,
77	      outputsPath,
78	      referencesPath,
79	      totalSamples
80	    },
81	    metrics: evaluations
